1	import { createHash } from "node:crypto";
2	import { CampRow, ClassRow } from "@cyc-seattle/clubspot";
3	import { PersonRow, ProgramRow } from "@cyc-seattle/crm";
4	import { AuditFindingRow } from "@cyc-seattle/directus";
5	import { GroupMember } from "@cyc-seattle/gsuite";
6	import { isValidEmail, MembershipTables, planProgramMemberPeople, planProgramMembers } from "./membership.js";
7	import { planGroupNesting } from "./nesting.js";
8	import { planGroupOwners } from "./owners.js";
9	import { GoogleGroupRow, ProgramWithGoogleGroup } from "./schema.js";
10	
11	/** Which sync raised a finding. `class_without_program` tags `clubspot-sync` even though this
12	 * pass computes it - see `findClassesWithoutProgram`. */
13	export const GSUITE_SYNC_SOURCE = "gsuite-sync";
14	export const CLUBSPOT_SYNC_SOURCE = "clubspot-sync";
15	
16	export type AuditFindingKind =
17	  | "unexpected_member"
18	  | "stale_member"
19	  | "settings_drift"
20	  | "missing_group"
21	  | "program_without_group"
22	  | "class_without_program"
23	  | "mismatched_revenue_account"
24	  | "invalid_email";
25	
26	/** Every kind this pass can raise. Scopes `planAuditFindingWrites` to the rows it owns, so it
27	 * never resolves a finding some other sync raised. */
28	export const AUDIT_FINDING_KINDS: readonly AuditFindingKind[] = [
29	  "unexpected_member",
30	  "stale_member",
31	  "settings_drift",
32	  "missing_group",
33	  "program_without_group",
34	  "class_without_program",
35	  "mismatched_revenue_account",
36	  "invalid_email",
37	];
38	
39	/** An `audit_findings` row before its `fingerprint` and `status` are attached. */
40	export interface AuditFindingInput {
41	  source: string;
42	  kind: AuditFindingKind;
43	  subject: string;
44	  detail: string;
45	}
46	
47	/**
48	 * `source` + `kind` + `subject` + a hash of `detail`, matching the schema's unique `fingerprint`
49	 * column. Hashing `detail` keeps the fingerprint's length independent of how long a finding's
50	 * message gets, while still changing whenever the substance of the finding does - which is what
51	 * lets `planAuditFindingWrites` tell "already raised" from "raised again with something new to say".
52	 */
53	export function fingerprintFinding(input: AuditFindingInput): string {
54	  const detailHash = createHash("sha256").update(input.detail).digest("hex");
55	  return `${input.source}:${input.kind}:${input.subject}:${detailHash}`;
56	}
57	
58	function normalizeEmail(email: string): string {
59	  return email.trim().toLowerCase();
60	}
61	
62	// Group managers are managed by hand until roles have one model (#156), so neither membership
63	// check audits them. Owners still are: config owners are in the plan, and a stray one is worth a look.
64	function isAudited(member: GroupMember): boolean {
65	  return member.role !== "MANAGER";
66	}
67	
68	/**
69	 * `unexpected_member` findings: a live member of `group` whose email isn't in `plannedEmails` -
70	 * the union every write pass would ever add there, ignoring the membership window (see
71	 * `plannedGroupMembers`'s `unwindowed` plan). Add-only means nobody already in a group is ever
72	 * compared against the plan until now; this is where a person who left the program, or was added
73	 * by hand for reasons the CRM doesn't know about, becomes visible for a human to decide about, not
74	 * flagged as an error. A member who aged out of the membership window but still has a real
75	 * registration or role is `stale_member` instead - see `findStaleMembers`.
76	 */
77	export function findUnexpectedMembers(
78	  group: Pick<GoogleGroupRow, "email">,
79	  plannedEmails: readonly string[],
80	  liveMembers: readonly GroupMember[],
81	): AuditFindingInput[] {
82	  const planned = new Set(plannedEmails.map(normalizeEmail));
83	  return liveMembers
84	    .filter((member) => isAudited(member) && !planned.has(normalizeEmail(member.email)))
85	    .map((member) => ({
86	      source: GSUITE_SYNC_SOURCE,
87	      kind: "unexpected_member" as const,
88	      subject: group.email,
89	      detail: `${normalizeEmail(member.email)} is a member of ${group.email} but isn't in the plan for it`,
90	    }));
91	}
92	
93	/**
94	 * `stale_member` findings: a live member of `group` who is in the unwindowed plan but not the
95	 * windowed one - a real registration or role, just one the membership window (#149) has aged past.
96	 * Add-only means they were added legitimately and are never removed automatically; this is what
97	 * keeps them from being misreported as `unexpected_member`.
98	 */
99	export function findStaleMembers(
100	  group: Pick<GoogleGroupRow, "email">,
101	  windowedEmails: readonly string[],
102	  unwindowedEmails: readonly string[],
103	  liveMembers: readonly GroupMember[],
104	): AuditFindingInput[] {
105	  const windowed = new Set(windowedEmails.map(normalizeEmail));
106	  const unwindowed = new Set(unwindowedEmails.map(normalizeEmail));
107	  return liveMembers
108	    .filter((member) => {
109	      const email = normalizeEmail(member.email);
110	      return isAudited(member) && unwindowed.has(email) && !windowed.has(email);
111	    })
112	    .map((member) => ({
113	      source: GSUITE_SYNC_SOURCE,
114	      kind: "stale_member" as const,
115	      subject: group.email,
116	      detail: `${normalizeEmail(member.email)} is a member of ${group.email} from a past season outside the membership window`,
117	    }));
118	}
119	
120	/** `missing_group` finding for a `google_groups` row whose address Workspace has no group for. */
121	export function findMissingGroup(group: Pick<GoogleGroupRow, "id" | "email">, exists: boolean): AuditFindingInput[] {
122	  if (exists) {
123	    return [];
124	  }
125	  return [
126	    {
127	      source: GSUITE_SYNC_SOURCE,
128	      kind: "missing_group",
129	      subject: group.email,
130	      detail: `google_groups row ${group.id ?? "?"} references ${group.email}, which doesn't exist in Workspace`,
131	    },
132	  ];
133	}
134	
135	/**
136	 * `missing_group` finding for an archived `google_groups` row a program still points at.
137	 * Archiving skips every other check for the row - see `runAudit` - so this is the one thing about
138	 * an archived row that still needs a human's attention: a program pointing at a group Workspace no
139	 * longer has.
140	 */
141	export function findMissingGroupForArchivedProgramGroup(
142	  group: Pick<GoogleGroupRow, "id" | "email">,
143	  isProgramGroup: boolean,
144	): AuditFindingInput[] {
145	  if (!isProgramGroup) {
146	    return [];
147	  }
148	  return [
149	    {
150	      source: GSUITE_SYNC_SOURCE,
151	      kind: "missing_group",
152	      subject: group.email,
153	      detail: `google_groups row ${group.id ?? "?"} for ${group.email} is archived, but a program still references it`,
154	    },
155	  ];
156	}
157	
158	/**
159	 * `program_without_group` findings: a `programs` row with no `google_group_id` set. That's the
160	 * only rule for whether a program gets a group, so this finding is what makes an omission visible
161	 * instead of silent.
162	 */
163	export function findProgramsWithoutGroup(programs: readonly ProgramWithGoogleGroup[]): AuditFindingInput[] {
164	  return programs
165	    .filter((program) => program.id && !program.google_group_id)
166	    .map((program) => ({
167	      source: GSUITE_SYNC_SOURCE,
168	      kind: "program_without_group" as const,
169	      subject: program.id as string,
170	      detail: `Program "${program.name}" (${program.id}) has no google_group_id`,
171	    }));
172	}
173	
174	/**
175	 * `class_without_program` findings: a `classes` row with no `program_id`, the hand-set link from
176	 * #149. This is a Clubspot-side gap - `program_id` lives on `classes` in `clubspot`'s own schema
177	 * and has nothing to do with a Google Group - so it's tagged `clubspot-sync` rather than
178	 * `gsuite-sync`, even though this pass is the one computing it today.
179	 */
180	export function findClassesWithoutProgram(classes: readonly ClassRow[]): AuditFindingInput[] {
181	  return classes
182	    .filter((cls) => cls.id && !cls.program_id)
183	    .map((cls) => ({
184	      source: CLUBSPOT_SYNC_SOURCE,
185	      kind: "class_without_program" as const,
186	      subject: cls.id as string,
187	      detail: `Class "${cls.name}" (${cls.id}) has no program_id`,
188	    }));
189	}
190	
191	/**
192	 * Everyone the membership pass would try to add right now, across every program whose group is
193	 * live: inside the membership window, so an old registration's bad address isn't reported.
194	 */
195	export function candidateMemberPeople(tables: AuditTables, now: Date): PersonRow[] {
196	  const liveGroupIds = new Set(tables.groups.filter((group) => group.id && !group.archived).map((group) => group.id));
197	  const people = new Map<string, PersonRow>();
198	  for (const program of tables.programs) {
199	    if (!program.id || !program.google_group_id || !liveGroupIds.has(program.google_group_id)) {
200	      continue;
201	    }
202	    for (const person of planProgramMemberPeople(program.id, tables, now)) {
203	      people.set(person.id as string, person);
204	    }
205	  }
206	  return [...people.values()];
207	}
208	
209	/**
210	 * `invalid_email` findings: a person whose `email` isn't a usable address. Membership skips them
211	 * (see `isValidEmail`), so this is where they surface to be fixed. The caller passes only
212	 * `candidateMemberPeople`, so nobody outside a current group is reported.
213	 * Fix it in Directus: clubspot-sync only fills empty `people` fields (#137), so a Clubspot-only
214	 * correction never lands.
215	 */
216	export function findInvalidEmails(
217	  people: readonly Pick<PersonRow, "id" | "first_name" | "last_name" | "email">[],
218	): AuditFindingInput[] {
219	  return people
220	    .filter((person) => person.id && person.email && person.email.trim() !== "" && !isValidEmail(person.email))
221	    .map((person) => ({
222	      source: CLUBSPOT_SYNC_SOURCE,
223	      kind: "invalid_email" as const,
224	      subject: person.id as string,
225	      detail: `${[person.first_name, person.last_name].filter(Boolean).join(" ") || "(no name)"} has an unusable email: "${person.email}"`,
226	    }));
227	}
228	
229	/**
230	 * `mismatched_revenue_account` findings: a camp whose classes map to programs with more than one
231	 * distinct, non-null `revenue_account`. A Clubspot Camp has a single sales account
232	 * (`clubspot_sales_account`), so every class within it should share one. A program with a null
233	 * `revenue_account` isn't mapped yet and doesn't itself count as a conflict - only two or more
234	 * distinct values do. Tagged `clubspot-sync`, the same as `class_without_program`: this is a
235	 * Clubspot/finance concern, not a Google one, even though this pass computes it.
236	 */
237	export function findMismatchedRevenueAccounts(
238	  camps: readonly Pick<CampRow, "id" | "name" | "clubspot_sales_account">[],
239	  classes: readonly ClassRow[],
240	  programs: readonly Pick<ProgramRow, "id" | "revenue_account">[],
241	): AuditFindingInput[] {
242	  const programById = new Map(
243	    programs.filter((program) => program.id).map((program) => [program.id as string, program]),
244	  );
245	
246	  const findings: AuditFindingInput[] = [];
247	  for (const camp of camps) {
248	    if (!camp.id) {
249	      continue;
250	    }
251	    const accounts = new Set<string>();
252	    for (const cls of classes) {
253	      if (cls.camp_id !== camp.id || !cls.program_id) {
254	        continue;
255	      }
256	      const revenueAccount = programById.get(cls.program_id)?.revenue_account;
257	      if (revenueAccount) {
258	        accounts.add(revenueAccount);
259	      }
260	    }
261	    if (accounts.size > 1) {
262	      findings.push({
263	        source: CLUBSPOT_SYNC_SOURCE,
264	        kind: "mismatched_revenue_account",
265	        subject: camp.id,
266	        detail: `Camp "${camp.name}" (${camp.id}, sales account ${camp.clubspot_sales_account ?? "none"}) has classes mapped to programs with different revenue_account values: ${[...accounts].sort().join(", ")}`,
267	      });
268	    }
269	  }
270	  return findings;
271	}
272	
273	/** Every row the audit pass needs to compute a group's full planned membership, regardless of
274	 * role - the union of what every write pass would add there. `camps` and `programs` carry the
275	 * extra fields `findMismatchedRevenueAccounts` and the membership window need, on top of what
276	 * `MembershipTables` itself requires. */
277	export interface AuditTables extends MembershipTables {
278	  groups: readonly GoogleGroupRow[];
279	  camps: readonly CampRow[];
280	  programs: readonly ProgramWithGoogleGroup[];
281	}
282	
283	/**
284	 * A group's planned membership under two views, both reachable from `MembershipTables`: `windowed`
285	 * is what a write pass would add today (participants inside the membership window, plus role
286	 * assignments, nested children, and owners); `unwindowed` additionally counts a class's
287	 * participants regardless of how long ago its camp ended. A live member in `unwindowed` but not
288	 * `windowed` has aged out rather than never belonged - see `findStaleMembers` vs
289	 * `findUnexpectedMembers`.
290	 */
291	export interface PlannedGroupMembers {
292	  windowed: string[];
293	  unwindowed: string[];
294	}
295	
296	/**
297	 * Whether some program points at `group`. Gates both membership auditing - an unmapped group has
298	 * no plan beyond its owners, so auditing it would report every member as unexpected, including
299	 * parent groups like `doublehanded@` whose only planned members are nested groups - and, for an
300	 * archived group, whether `missing_group` is worth raising at all.
301	 */
302	export function isProgramGroup(
303	  group: Pick<GoogleGroupRow, "id">,
304	  programs: readonly Pick<ProgramWithGoogleGroup, "google_group_id">[],
305	): boolean {
306	  return group.id != null && programs.some((program) => program.google_group_id === group.id);
307	}
308	
309	/**
310	 * Computes both membership views for `group`: program members (participants, guardians, and role
311	 * assignments - see `planProgramMembers`), nested child groups, and owners. This is deliberately
312	 * the union of every role - `findUnexpectedMembers`/`findStaleMembers` only care whether someone
313	 * belongs at all, not which role they hold.
314	 */
315	export function plannedGroupMembers(
316	  group: Pick<GoogleGroupRow, "id">,
317	  tables: AuditTables,
318	  now: Date,
319	  groupOwners: readonly string[],
320	): PlannedGroupMembers {
321	  const windowed = new Set<string>();
322	  const unwindowed = new Set<string>();
323	
324	  for (const program of tables.programs) {
325	    if (!program.id || program.google_group_id !== group.id) {
326	      continue;
327	    }
328	    for (const email of planProgramMembers(program.id, tables, now)) {
329	      windowed.add(email);
330	      unwindowed.add(email);
331	    }
332	    for (const email of planProgramMembers(program.id, tables, now, { ignoreCampWindow: true })) {
333	      unwindowed.add(email);
334	    }
335	  }
336	
337	  for (const { child, parent } of planGroupNesting(tables.groups)) {
338	    if (parent.id === group.id) {
339	      windowed.add(normalizeEmail(child.email));
340	      unwindowed.add(normalizeEmail(child.email));
341	    }
342	  }
343	
344	  for (const email of planGroupOwners(groupOwners)) {
345	    windowed.add(email);
346	    unwindowed.add(email);
347	  }
348	
349	  return { windowed: [...windowed], unwindowed: [...unwindowed] };
350	}
351	
352	export interface AuditFindingWrites {
353	  toCreate: readonly AuditFindingInput[];
354	  /** Open rows to mark `resolved` - their condition wasn't raised again this run. */
355	  toResolve: readonly AuditFindingRow[];
356	  /** Resolved rows to reopen - their fingerprint recurred, so the row is reused rather than
357	   * colliding with a fresh insert under the unique `fingerprint` column. */
358	  toReopen: readonly AuditFindingRow[];
359	}
360	
361	/**
362	 * Reconciles this run's findings, deduped by fingerprint, against the `audit_findings` rows this
363	 * pass owns (scoped by `AUDIT_FINDING_KINDS`, so a row some other sync raised is untouched). A row
364	 * toggles between `open` and `resolved` as its condition recurs or clears; `dismissed` rows never
365	 * change, since a human already reviewed them.
366	 */
367	export function planAuditFindingWrites(
368	  findings: readonly AuditFindingInput[],
369	  existingRows: readonly AuditFindingRow[],
370	): AuditFindingWrites {
371	  const freshByFingerprint = new Map<string, AuditFindingInput>();
372	  for (const finding of findings) {
373	    freshByFingerprint.set(fingerprintFinding(finding), finding);
374	  }
375	
376	  const ownedKinds: readonly string[] = AUDIT_FINDING_KINDS;
377	  const ownedRows = existingRows.filter((row) => ownedKinds.includes(row.kind));
378	  const existingFingerprints = new Set(ownedRows.map((row) => row.fingerprint));
379	
380	  const toCreate = [...freshByFingerprint.entries()]
381	    .filter(([fingerprint]) => !existingFingerprints.has(fingerprint))
382	    .map(([, finding]) => finding);
383	
384	  const toResolve = ownedRows.filter((row) => row.status === "open" && !freshByFingerprint.has(row.fingerprint));
385	  const toReopen = ownedRows.filter((row) => row.status === "resolved" && freshByFingerprint.has(row.fingerprint));
386	
387	  return { toCreate, toResolve, toReopen };
388	}
